def investigate(context, acquire):
    receipts = context.get('receipts', [])
    seen = set()
    for row in receipts:
        query = row.get('query')
        if isinstance(query, dict):
            key = tuple(sorted((a.get('op'), a.get('id')) for a in query.get('actions', [])))
            seen.add(key)
    actions = [
        {'op': 'put', 'id': 5},
        {'op': 'begin'},
        {'op': 'put', 'id': 9},
        {'op': 'rollback'},
        {'op': 'put', 'id': 7}
    ]
    key = tuple(sorted((a.get('op'), a.get('id')) for a in actions))
    if key in seen:
        return {'query': None, 'note': {'reason': 'duplicate'}}
    return {'query': {'actions': actions}, 'note': {'hypothesis': 'AUTOINCREMENT tracks the largest ever inserted ID, not the current maximum; rollback restores rows but not sqlite_sequence'}}

